#!/usr/bin/env bash
# Maintainer tool: prove that the Python skills, as written, build a working service.
#
# It creates a fresh `uv init --package` project, writes every file that the Python skills ship as
# reference code (a fenced block under a heading that is just a backticked path, in any SKILL.md or
# references/*.md of plugins/ai-toolkit-python-*), adds an empty __init__.py to every package
# directory, runs the steps the skills describe in prose (`alembic init`, the alembic.ini edits, an
# autogenerated first migration) and then runs the whole verify sequence:
#   ruff check, ruff format --check, mypy --strict, lint-imports,
#   unit tests with the coverage gate, integration tests (PostgreSQL/Redis/Kafka via testcontainers),
#   docker build, and a docker run + docker stop of the image.
# No hand-written glue: a failure here means a skill is wrong or incomplete.
#
# Usage: bash tools/render-python-proof.sh [--dir DIR] [--keep] [--skip-integration] [--skip-docker]
#   --dir DIR           render into DIR (must not exist) instead of a temporary directory
#   --keep              keep the rendered project (always kept on failure; its path is printed)
#   --skip-integration  skip the testcontainers suite and the migration autogenerate (no Docker needed)
#   --skip-docker       skip the image build and the container smoke test
# Needs: uv, python3, and Docker (Colima works; DOCKER_HOST and
# TESTCONTAINERS_DOCKER_SOCKET_OVERRIDE=/var/run/docker.sock are set when missing).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORK=""
KEEP=0
SKIP_INTEGRATION=0
SKIP_DOCKER=0
while [ $# -gt 0 ]; do
  case "$1" in
    --dir) WORK="$2"; shift 2 ;;
    --keep) KEEP=1; shift ;;
    --skip-integration) SKIP_INTEGRATION=1; shift ;;
    --skip-docker) SKIP_DOCKER=1; shift ;;
    -h|--help) sed -n '2,22p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

command -v uv >/dev/null || { echo "uv is required" >&2; exit 2; }
command -v python3 >/dev/null || { echo "python3 is required" >&2; exit 2; }
NEEDS_DOCKER=0
if [ "$SKIP_INTEGRATION" -eq 0 ] || [ "$SKIP_DOCKER" -eq 0 ]; then NEEDS_DOCKER=1; fi
if [ "$NEEDS_DOCKER" -eq 1 ]; then
  command -v docker >/dev/null || { echo "docker is required (or pass --skip-integration --skip-docker)" >&2; exit 2; }
  if [ -z "${DOCKER_HOST:-}" ] && [ ! -S /var/run/docker.sock ]; then
    DOCKER_HOST="$(docker context inspect --format '{{.Endpoints.docker.Host}}')"
    export DOCKER_HOST
  fi
  export TESTCONTAINERS_DOCKER_SOCKET_OVERRIDE="${TESTCONTAINERS_DOCKER_SOCKET_OVERRIDE:-/var/run/docker.sock}"
  docker info >/dev/null 2>&1 || { echo "the Docker daemon is not reachable" >&2; exit 2; }
fi

if [ -z "$WORK" ]; then WORK="$(mktemp -d "${TMPDIR:-/tmp}/render-python-proof.XXXXXX")"; else mkdir "$WORK"; fi
PROJECT="$WORK/my-service"
EXTRACT="$WORK/extract.py"
CONTAINERS=()
STATUS=1

cleanup() {
  for c in ${CONTAINERS[@]+"${CONTAINERS[@]}"}; do docker rm -f "$c" >/dev/null 2>&1 || true; done
  if [ "$STATUS" -eq 0 ] && [ "$KEEP" -eq 0 ]; then rm -rf "$WORK"; else echo "project kept at: $PROJECT"; fi
}
trap cleanup EXIT

step() { printf '\n==> %s\n' "$*"; }

cat > "$EXTRACT" <<'PY'
import re
import sys
from pathlib import Path

root, project = Path(sys.argv[1]), Path(sys.argv[2])
mode = sys.argv[3]
HOLD = {"src/my_service/alembic/env.py"}
HEADING = re.compile(r"^#{2,4} `([^`]+)`\s*$")
PATH_LIKE = re.compile(r"^[\w./#-]+$")

blocks = {}
for doc in sorted(root.glob("plugins/ai-toolkit-python-*/skills/*/**/*.md")):
    lines = doc.read_text().split("\n")
    for i, line in enumerate(lines):
        match = HEADING.match(line)
        if not match or not PATH_LIKE.match(match.group(1)):
            continue
        j = i + 1
        while j < len(lines) and not lines[j].strip():
            j += 1
        if j >= len(lines) or not lines[j].startswith("```"):
            continue
        k = j + 1
        while not lines[k].startswith("```"):
            k += 1
        path = match.group(1)
        if path in blocks:
            sys.exit("duplicate block for %s: %s and %s" % (path, blocks[path][0], doc))
        blocks[path] = (doc, "\n".join(lines[j + 1 : k]) + "\n")

if mode == "main":
    written = 0
    for path, (doc, text) in sorted(blocks.items()):
        if "#" in path or path in HOLD:
            continue
        target = project / path
        target.parent.mkdir(parents=True, exist_ok=True)
        if path == "pyproject.toml":
            generated = re.search(r'(?ms)^\[build-system\]\n(requires = \[[^\n]*\])', target.read_text())
            if generated:
                text = re.sub(r'(?m)^requires = \[[^\n]*\]', lambda _: generated.group(1), text, count=1)
        if path == "Dockerfile":
            text = text.replace("<uv-version>", sys.argv[4])
        target.write_text(text)
        written += 1
    for base in (project / "src" / "my_service", project / "tests"):
        for directory in [base, *[d for d in base.rglob("*") if d.is_dir()]]:
            if directory.name in {"__pycache__", "versions"}:
                continue
            init = directory / "__init__.py"
            if not init.exists():
                init.write_text("")
    print("rendered %d files from the Python skills" % written)
elif mode == "alembic":
    hooks = blocks["alembic.ini#post_write_hooks"][1]
    ini = project / "alembic.ini"
    text = ini.read_text()
    text = re.sub(r"(?m)^script_location = .*$", "script_location = my_service:alembic", text, count=1)
    text = re.sub(r"(?ms)^\[post_write_hooks\]\n.*?(?=^\[loggers\])", hooks + "\n", text, count=1)
    ini.write_text(text)
    env = project / "src/my_service/alembic/env.py"
    env.write_text(blocks["src/my_service/alembic/env.py"][1])
    print("patched alembic.ini and wrote env.py")
PY

step "uv init --package my-service"
(cd "$WORK" && uv init --package --python 3.14 --vcs none my-service >/dev/null)
UV_VERSION="$(uv --version | awk '{print $2}')"
python3 "$EXTRACT" "$ROOT" "$PROJECT" main "$UV_VERSION"
: > "$PROJECT/src/my_service/__init__.py"   # python-code-structure §1b: empty the stub `uv init --package` writes

cd "$PROJECT"
step "uv sync"
uv sync

step "alembic init, alembic.ini edits, env.py"
uv run alembic init -t async src/my_service/alembic >/dev/null
python3 "$EXTRACT" "$ROOT" "$PROJECT" alembic

if [ "$SKIP_INTEGRATION" -eq 0 ]; then
  step "autogenerate the first migration against an empty PostgreSQL"
  PG="render-proof-pg-$$"
  CONTAINERS+=("$PG")
  docker run -d --name "$PG" -e POSTGRES_PASSWORD=proof -p 127.0.0.1::5432 postgres:16-alpine >/dev/null
  for _ in $(seq 1 60); do
    docker exec "$PG" pg_isready -U postgres >/dev/null 2>&1 && break
    sleep 1
  done
  sleep 2
  PG_PORT="$(docker port "$PG" 5432/tcp | head -n1 | sed 's/.*://')"
  DB_URL="postgresql+asyncpg://postgres@127.0.0.1:${PG_PORT}/postgres" DB_PASSWORD=proof \
    uv run alembic revision --autogenerate -m "initial schema"
  docker rm -f "$PG" >/dev/null
fi

step "ruff check"
uv run ruff check .
step "ruff format --check"
uv run ruff format --check .
step "mypy --strict"
uv run mypy
step "lint-imports"
uv run lint-imports

step "unit tests with the coverage gate"
uv run pytest -m "not integration" --cov 2>&1 | tee "$WORK/unit.log" | tail -n 25

if [ "$SKIP_INTEGRATION" -eq 0 ]; then
  step "integration tests (PostgreSQL, Redis, Kafka through testcontainers)"
  uv run pytest -m integration 2>&1 | tee "$WORK/integration.log" | tail -n 15
fi

if [ "$SKIP_DOCKER" -eq 0 ]; then
  step "docker build"
  if docker buildx version >/dev/null 2>&1; then
    docker buildx build -t my-service:render-proof --load .
  elif command -v docker-buildx >/dev/null 2>&1; then
    docker-buildx build -t my-service:render-proof --load .
  else
    DOCKER_BUILDKIT=1 docker build -t my-service:render-proof .
  fi

  step "docker run + docker stop (uvicorn is PID 1)"
  APP="render-proof-app-$$"
  CONTAINERS+=("$APP")
  docker run -d --name "$APP" -p 127.0.0.1::8000 \
    -e DB_URL="postgresql+asyncpg://app@127.0.0.1:1/app" -e DB_PASSWORD=unused \
    my-service:render-proof >/dev/null
  APP_PORT="$(docker port "$APP" 8000/tcp | head -n1 | sed 's/.*://')"
  for _ in $(seq 1 60); do
    curl -fsS "http://127.0.0.1:${APP_PORT}/health/live" >/dev/null 2>&1 && break
    sleep 1
  done
  curl -fsS "http://127.0.0.1:${APP_PORT}/health/live"; echo
  docker stop "$APP" >/dev/null
  EXIT_CODE="$(docker inspect --format '{{.State.ExitCode}}' "$APP")"
  echo "container exit code after docker stop: $EXIT_CODE"
  [ "$EXIT_CODE" = "0" ] || { echo "expected 0 for uvicorn as PID 1" >&2; exit 1; }
  docker rm -f "$APP" >/dev/null
  docker image rm my-service:render-proof >/dev/null 2>&1 || true
fi

STATUS=0
printf '\nGREEN: the Python skills rendered, linted, type-checked, tested and built.\n'
grep -E "^TOTAL|Required test coverage" "$WORK/unit.log" || true
tail -n 1 "$WORK/unit.log"
if [ "$SKIP_INTEGRATION" -eq 0 ]; then tail -n 1 "$WORK/integration.log"; fi
